import math


def multiply(a, b):
    result = [0.0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            result[i + j] += x * y
    return result


def bump_power(start, width, amplitude):
    # amplitude * q^2 * (1-q)^2, q=start+width*v.
    return [amplitude * value for value in multiply(
        multiply([start, width], [start, width]),
        multiply([1-start, -width], [1-start, -width]),
    )]


def bernstein4(power):
    return [sum(power[j] * math.comb(k, j) / math.comb(4, j)
                for j in range(k + 1)) for k in range(5)]


