def c1_conic_controls(native_poles, native_weights):
    # Multiply each exact rational quadratic homogeneous arc by
    # h(v)=1+v-v^2 (Bernstein controls1,1.5,1). This leaves its projected
    # geometry unchanged, and cancels the endpoint denominator derivatives.
    # Adjacent homogeneous first derivatives now match, permitting C1 knots.
