        for k in range(5):
            numerator = [0.0,0.0,0.0]
            weight = 0.0
            for i in range(3):
                j = k-i
                if not 0 <= j <= 2:
                    continue
                factor = (math.comb(2,i)*math.comb(2,j)/math.comb(4,k)
                          * native_weights[indices[i]]*h[j])
